pub fn report(s:&HandoffState)->Result<Value>{let s=&s.0;Ok(json!({"protocol":PROTOCOL,"revision":s["revision"],"spent":s["core"]["spent"],"reserved":s["core"]["reserved"],"pendingDeliveries":values(&s["deliveries"])?.iter().filter(|d|d["state"]=="PENDING").count().to_string(),"openHolds":values(&s["holds"])?.iter().filter(|h|h["state"]=="OPEN").map(|h|json!({"id":h["holdId"],"reason":h["reason"]["code"],"members":h["members"]})).collect::<Vec<_>>(),"unresolvedOperations":values(&s["core"]["operations"])?.iter().filter(|o|o["effect"]=="UNKNOWN").map(|o|o["id"].clone()).collect::<Vec<_>>()}))}

pub fn metrics(state:&HandoffState)->Result<Value>{let s=&state.0;let mut deliveries=json!({});for k in ["PENDING","CLAIMED","ACKNOWLEDGED","INVALIDATED","EXCLUDED"]{deliveries[k]=json!(values(&s["deliveries"])?.iter().filter(|d|d["state"]==k).count().to_string());}let mut count=0;for (rid,run) in s["core"]["runs"].as_object().unwrap(){if let Some(nodes)=run.get("nodes").and_then(Value::as_object){for nid in nodes.keys(){if blocked(state,rid,Some(nid)){count+=1;}}}}Ok(json!({"deliveries":deliveries,"openHolds":values(&s["holds"])?.iter().filter(|h|h["state"]=="OPEN").count().to_string(),"blockedNodes":count.to_string(),"manifests":values(&s["manifests"])?.len().to_string(),"consumptions":values(&s["consumptions"])?.len().to_string()}))}
